import sys

def search_range_brute(nums, target):
    n = len(nums)
    first = -1
    last = -1
    for i, x in enumerate(nums):
        if x == target:
            if first == -1:
                first = i
            last = i
    return first, last

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    t = int(data[1 + n])
    f, l = search_range_brute(nums, t)
    print(f, l)

import sys

def search_range_opt(nums, target):
    n = len(nums)
    def lower_bound(nums, t):
        lo, hi = 0, n - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] < t:
                lo = mid + 1
            else:
                hi = mid - 1
        return lo
    def upper_bound(nums, t):
        lo, hi = 0, n - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] <= t:
                lo = mid + 1
            else:
                hi = mid - 1
        return hi
    first = lower_bound(nums, target)
    last = upper_bound(nums, target)
    if first > last or (first < n and nums[first] != target):
        return -1, -1
    return first, last

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    t = int(data[1 + n])
    f, l = search_range_opt(nums, t)
    print(f, l)
